<?php
declare(strict_types=1);
namespace App\Models\Repositories;
use PDO;
final class AdminRepository { public function __construct(private PDO $db){}
 public function isAdmin(int $id):bool{$s=$this->db->prepare("SELECT 1 FROM users WHERE id=:id AND role='super_admin'");$s->execute(['id'=>$id]);return(bool)$s->fetchColumn();}
 public function overview():array{$plans=$this->db->query("SELECT p.name,p.code,COUNT(s.id) subscribers,SUM(s.status='active') active FROM plans p LEFT JOIN subscriptions s ON s.plan_id=p.id GROUP BY p.id")->fetchAll();$overdue=$this->db->query("SELECT u.id,u.full_name,u.email,COALESCE(SUM(f.amount_cents),0) amount_cents FROM users u JOIN financial_transactions f ON f.user_id=u.id WHERE f.status='overdue' GROUP BY u.id ORDER BY amount_cents DESC")->fetchAll();$totals=$this->db->query("SELECT SUM(status='paid') paid_count,SUM(status='overdue') overdue_count,COALESCE(SUM(CASE WHEN status='paid' THEN amount_cents ELSE 0 END),0) revenue FROM financial_transactions")->fetch()?:[];return compact('plans','overdue','totals');}
 public function block(int $user,string $reason):void{$s=$this->db->prepare("UPDATE users SET access_blocked_at=NOW(),block_reason=:reason WHERE id=:id AND role='user'");$s->execute(['id'=>$user,'reason'=>$reason]);}
 public function unblock(int $user):void{$s=$this->db->prepare('UPDATE users SET access_blocked_at=NULL,block_reason=NULL WHERE id=:id');$s->execute(['id'=>$user]);}
 public function processPayment(string $provider,string $eventId,array $payload):void{$this->db->beginTransaction();try{$e=$this->db->prepare('INSERT IGNORE INTO payment_events(provider,provider_event_id,event_type,payload,processed_at) VALUES(:p,:id,:type,:payload,NOW())');$e->execute(['p'=>$provider,'id'=>$eventId,'type'=>$payload['type']??$payload['event']??'payment','payload'=>json_encode($payload)]);if(!$e->rowCount()){$this->db->commit();return;}$resource=$payload['resource']??$payload;$ref=(string)($resource['reference_id']??$resource['external_reference']??'');$status=strtolower((string)($resource['status']??''));$map=['approved'=>'paid','paid'=>'paid','refunded'=>'refunded','chargeback'=>'refunded','cancelled'=>'cancelled','canceled'=>'cancelled','expired'=>'overdue','declined'=>'overdue','denied'=>'overdue'];if($ref&&isset($map[$status])){$local=$map[$status];$f=$this->db->prepare('UPDATE financial_transactions SET status=:s,paid_at=IF(:s="paid",NOW(),paid_at) WHERE provider=:p AND provider_reference=:r');$f->execute(['s'=>$local,'p'=>$provider,'r'=>$ref]);if($local==='paid'){$this->db->prepare("UPDATE subscriptions SET status='active',starts_at=COALESCE(starts_at,NOW()),ends_at=IF(payment_method='credit_card',NULL,DATE_ADD(NOW(),INTERVAL 1 MONTH)) WHERE provider=:p AND provider_reference=:r")->execute(['p'=>$provider,'r'=>$ref]);}elseif(in_array($local,['overdue','cancelled'],true)){$this->db->prepare("UPDATE subscriptions SET status=IF(:s='overdue','past_due','cancelled') WHERE provider=:p AND provider_reference=:r")->execute(['s'=>$local,'p'=>$provider,'r'=>$ref]);}$u=$this->db->prepare('SELECT DISTINCT user_id FROM financial_transactions WHERE provider=:p AND provider_reference=:r');$u->execute(['p'=>$provider,'r'=>$ref]);foreach($u->fetchAll() as $row){if($local==='paid')$this->unblock((int)$row['user_id']);else if($local==='overdue')$this->block((int)$row['user_id'],'Pagamento '.$status);}}$this->db->commit();}catch(\Throwable $x){$this->db->rollBack();throw$x;}}
}
